// Renders generated files from the SPARC data (pure functions, no I/O):
//   renderRoomTypes()  -> sparc-ui/contracts/rooms.d.ts (TypeScript contracts)
//   renderScopeDoc()   -> docs/SPARC_SCOPE.md          (readable scope for sign-off)
// Run `npm run sparc:generate` after editing rooms, shapes, levels or blueprints.
// test/sparc.test.js fails if the files on disk are out of date.
import { toDocType, toTs } from "./propSpec.js";
import { ROOMS, SHAPES } from "./rooms.js";
import { STYLE_LEVELS, STYLE_LEVEL_IDS, BASE_PACKAGES, V1_WORKFLOW_LEVELS } from "./styleLevels.js";
import { libraryTargets, loadBlueprints, roomsOf } from "./index.js";

const HEADER = "AUTO-GENERATED by `npm run sparc:generate` from platform-backend-main/sparc/. Do not edit by hand.";

export const pascal = (id) => id.replace(/(^|-)([a-z0-9])/g, (_, __, c) => c.toUpperCase());
export const propsTypeName = (roomId) => `${pascal(roomId)}Props`;

const jsdoc = (text, indent = "") => `${indent}/** ${text.replace(/\*\//g, "* /")} */\n`;

function renderFields(fields, indent = "  ") {
  return Object.entries(fields)
    .map(([name, spec]) => {
      const key = /^[a-zA-Z_$][\w$]*$/.test(name) ? name : JSON.stringify(name);
      return `${jsdoc(spec.description, indent)}${indent}${key}${spec.required ? "" : "?"}: ${toTs(spec)};`;
    })
    .join("\n");
}

export function renderRoomTypes() {
  const out = [];
  out.push(`// ${HEADER}`);
  out.push("// Plug shapes: every component placed in a room, at any style level, must accept these props.");
  out.push('import type { ReactNode } from "react";');
  out.push("");
  out.push("// ---- Shared shapes ----");
  for (const [name, def] of Object.entries(SHAPES)) {
    out.push(jsdoc(def.description).trimEnd());
    out.push(`export interface ${name} {\n${renderFields(def.fields)}\n}`);
    out.push("");
  }
  out.push("// ---- Rooms ----");
  for (const [id, room] of Object.entries(ROOMS)) {
    out.push(jsdoc(`Room "${id}" (${room.kind}): ${room.description}`).trimEnd());
    out.push(`export interface ${propsTypeName(id)} {\n${renderFields(room.props)}\n}`);
    out.push("");
  }
  out.push(`export type RoomId =\n${Object.keys(ROOMS).map((id) => `  | ${JSON.stringify(id)}`).join("\n")};`);
  out.push("");
  out.push("/** Room id -> its props type. */");
  out.push(`export interface RoomPropsMap {\n${Object.keys(ROOMS).map((id) => `  ${JSON.stringify(id)}: ${propsTypeName(id)};`).join("\n")}\n}`);
  out.push("");
  out.push(`export type StyleLevel = ${STYLE_LEVEL_IDS.map((l) => JSON.stringify(l)).join(" | ")};`);
  out.push("");
  return out.join("\n");
}

const cell = (s) => String(s ?? "").replace(/\|/g, "\\|").replace(/\n/g, " ");

export function renderScopeDoc(blueprints = loadBlueprints()) {
  const active = blueprints.filter((b) => b.status === "active");
  const planned = blueprints.filter((b) => b.status === "planned");
  const targets = libraryTargets(blueprints);
  const L = [];
  L.push(`<!-- ${HEADER} -->`);
  L.push("# SPARC AI — Scope (V1)");
  L.push("");
  L.push("This page is generated from the data in `platform-backend-main/sparc/`, so it always matches what the code checks.");
  L.push("");
  L.push(
    `**In numbers:** ${active.length} website types active, ${planned.length} planned · ${Object.keys(ROOMS).length} rooms · ${Object.keys(SHAPES).length} shared shapes · ${STYLE_LEVEL_IDS.length} style levels · **${targets.total} components** needed for V1.`
  );
  L.push("");

  L.push("## 1. Website types");
  L.push("");
  L.push("| Type | Status | Industries | Max style | Existing templates |");
  L.push("|---|---|---|---|---|");
  for (const b of blueprints) {
    L.push(
      `| **${cell(b.name)}** (\`${b.id}\`) | ${b.status} (${b.release}) | ${b.industries.length ? b.industries.join(", ") : "—"} | ${STYLE_LEVELS[b.maxStyleLevel].label} | ${b.existingTemplates.length ? b.existingTemplates.join(", ") : "—"} |`
    );
  }
  L.push("");

  for (const b of active) {
    L.push(`### ${b.name}`);
    L.push("");
    L.push(b.description);
    L.push("");
    L.push(`- ✅ **Must have:** ${b.rooms.required.join(", ")}`);
    L.push(`- ➕ **Optional:** ${b.rooms.optional.map((r) => (b.rooms.defaultOn.includes(r) ? `${r} *(on by default)*` : r)).join(", ")}`);
    const defaults = Object.entries(b.industryDefaults);
    if (defaults.length) L.push(`- 🏭 **Switched on per industry:** ${defaults.map(([i, r]) => `${i} → ${r.join(", ")}`).join("; ")}`);
    if (b.modulesFrom) L.push(`- 📦 **Modules:** ${b.modulesFrom}`);
    L.push("");
    L.push("| Page | Path | Rooms (in order) |");
    L.push("|---|---|---|");
    for (const pg of b.pages) {
      const notes = [pg.repeat ? "one per module" : "", pg.when ? `only if ${pg.when} is on` : ""].filter(Boolean).join(", ");
      L.push(`| ${cell(pg.title)}${notes ? ` *(${notes})*` : ""} | \`${pg.path}\` | ${pg.rooms.join(" → ")} |`);
    }
    L.push("");
  }
  for (const b of planned) {
    L.push(`### ${b.name} *(planned for ${b.release})*`);
    L.push("");
    L.push(b.description);
    L.push("");
    L.push(`- ✅ **Must have:** ${b.plannedRooms.required.join(", ")}`);
    L.push(`- ➕ **Optional:** ${b.plannedRooms.optional.join(", ")}`);
    if (b.notes) L.push(`- 📝 ${b.notes}`);
    L.push("");
  }

  L.push("## 2. Style levels");
  L.push("");
  L.push(`Every level may use: ${BASE_PACKAGES.map((p) => `\`${p}\``).join(", ")}.`);
  L.push("");
  L.push("| Level | Look | Motion | Extra packages | Reduce-motion | Max size / component | Site speed (Lighthouse) | Sources |");
  L.push("|---|---|---|---|---|---|---|---|");
  for (const id of STYLE_LEVEL_IDS) {
    const s = STYLE_LEVELS[id];
    L.push(
      `| **${s.label}** | ${cell(s.summary)} | ${s.motion} | ${s.allowedPackages.length ? s.allowedPackages.map((p) => `\`${p}\``).join(", ") : "none"} | ${s.reducedMotion ? "required" : "—"} | ${s.maxComponentKb} KB | ≥ ${s.minLighthouse} | ${s.sources.join(", ")} |`
    );
  }
  L.push("");
  L.push(`Workflow rooms get ${V1_WORKFLOW_LEVELS.length} skins in V1 (${V1_WORKFLOW_LEVELS.join(", ")}); visual rooms get every level their website types allow.`);
  L.push("");

  L.push("## 3. Rooms and their plug shapes");
  L.push("");
  L.push("Every component for a room must accept these props. **Bold** = required.");
  L.push("");
  for (const [id, room] of Object.entries(ROOMS)) {
    const users = blueprints.filter((b) => b.status === "active" && roomsOf(b).includes(id)).map((b) => b.id);
    L.push(`### \`${id}\` · ${room.kind} · ${room.category}`);
    L.push("");
    L.push(`${room.description} *Used by: ${users.join(", ")}.*`);
    L.push("");
    L.push("| Prop | Type | Meaning |");
    L.push("|---|---|---|");
    for (const [name, spec] of Object.entries(room.props)) {
      L.push(`| ${spec.required ? `**${name}**` : name} | ${cell(toDocType(spec))} | ${cell(spec.description)} |`);
    }
    L.push("");
  }

  L.push("## 4. Shared shapes");
  L.push("");
  for (const [name, def] of Object.entries(SHAPES)) {
    const fields = Object.entries(def.fields)
      .map(([f, spec]) => `${spec.required ? `**${f}**` : f}: ${toDocType(spec)}`)
      .join(" · ");
    L.push(`- **${name}**: ${def.description} — ${fields}`);
  }
  L.push("");

  L.push("## 5. Library targets for V1");
  L.push("");
  L.push(`**${targets.total} components** in total (one per room per style level it must support).`);
  L.push("");
  L.push("| Room | Kind | Website types | Levels | Count |");
  L.push("|---|---|---|---|---|");
  for (const r of targets.rows) {
    L.push(`| ${r.room} | ${r.kind} | ${r.websiteTypes.join(", ")} | ${r.levels.join(", ")} | ${r.levels.length} |`);
  }
  L.push("");
  L.push("`form-field` components must together cover all field types at each level (one component may cover several types).");
  L.push("");
  return L.join("\n");
}
